WITH session_summary AS (SELECT session_id, SUM(CASE WHEN event_type = 'page_view' THEN duration_sec ELSE 0 END) AS page_view_duration_sec FROM web_events WHERE duration_sec BETWEEN 146 AND 319 GROUP BY session_id) SELECT s.customer_id, s.device, ss.page_view_duration_sec FROM sessions s LEFT JOIN session_summary ss ON s.id = ss.session_id;
